<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b0f17;
        --panel: #111827;
        --panel-2: #0f172a;
        --text: #e5e7eb;
        --muted: #9ca3af;
        --border: rgba(255, 255, 255, 0.08);
        --accent: #ef4444;
        --accent-hover: #f87171;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(59, 130, 246, 0.16), transparent 35%),
          linear-gradient(180deg, #060913 0%, var(--bg) 100%);
        color: var(--text);
      }

      .page {
        width: min(92vw, 760px);
        padding: 24px;
      }

      .card {
        background: rgba(17, 24, 39, 0.88);
        border: 1px solid var(--border);
        border-radius: 24px;
        padding: 20px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      .preview {
        display: grid;
        gap: 16px;
      }

      .preview img {
        width: 100%;
        display: block;
        border-radius: 18px;
        aspect-ratio: 16 / 10;
        object-fit: cover;
        border: 1px solid rgba(255, 255, 255, 0.07);
      }

      .meta h1 {
        margin: 0 0 8px;
        font-size: clamp(1.35rem, 2vw, 1.9rem);
      }

      .meta p {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      .trigger {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 600;
        color: #fff;
        background: linear-gradient(180deg, #fb7185 0%, #ef4444 100%);
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(239, 68, 68, 0.28);
        transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
      }

      .trigger:hover {
        transform: translateY(-1px);
        filter: brightness(1.05);
        box-shadow: 0 16px 30px rgba(239, 68, 68, 0.34);
      }

      .trigger:focus-visible,
      .close-btn:focus-visible,
      .confirm-btn:focus-visible {
        outline: 2px solid #93c5fd;
        outline-offset: 3px;
      }

      dialog {
        width: min(92vw, 460px);
        border: 1px solid var(--border);
        border-radius: 22px;
        padding: 0;
        color: var(--text);
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(15, 23, 42, 0.98));
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(2, 6, 23, 0.72);
        backdrop-filter: blur(4px);
      }

      .dialog-body {
        padding: 24px;
      }

      .dialog-header {
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 16px;
        margin-bottom: 18px;
      }

      .dialog-icon {
        width: 44px;
        height: 44px;
        border-radius: 50%;
        display: grid;
        place-items: center;
        background: rgba(239, 68, 68, 0.16);
        color: #fca5a5;
        flex: none;
      }

      .dialog-title {
        margin: 0 0 6px;
        font-size: 1.15rem;
      }

      .dialog-text {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .close-btn {
        appearance: none;
        border: 0;
        background: transparent;
        color: var(--muted);
        font-size: 1.25rem;
        line-height: 1;
        cursor: pointer;
        padding: 4px;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .secondary,
      .confirm-btn {
        appearance: none;
        border-radius: 999px;
        padding: 0.85rem 1.1rem;
        font: inherit;
        font-weight: 600;
        cursor: pointer;
        border: 1px solid transparent;
      }

      .secondary {
        background: rgba(255, 255, 255, 0.04);
        color: var(--text);
        border-color: rgba(255, 255, 255, 0.08);
      }

      .confirm-btn {
        background: linear-gradient(180deg, #ef4444 0%, #dc2626 100%);
        color: #fff;
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="card preview" aria-labelledby="preview-title">
        <img
          src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
          alt="Preview of an uploaded image"
        />
        <div class="meta">
          <h1 id="preview-title">Library image</h1>
          <p>This image is currently stored in your library.</p>
        </div>
        <div class="actions">
          <button class="trigger" type="button">Delete image</button>
        </div>
      </section>
    </main>

    <dialog id="confirm-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <div class="dialog-body">
        <div class="dialog-header">
          <div style="display: flex; gap: 14px; align-items: flex-start;">
            <div class="dialog-icon" aria-hidden="true">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" role="presentation">
                <path
                  d="M12 9v4m0 4h.01M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z"
                  stroke="currentColor"
                  stroke-width="1.8"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                />
              </svg>
            </div>
            <div>
              <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
              <p class="dialog-text" id="dialog-description">
                This will permanently remove the image from your library. This action cannot be undone.
              </p>
            </div>
          </div>
          <button class="close-btn" type="button" aria-label="Close dialog">&times;</button>
        </div>
        <div class="dialog-actions">
          <button class="secondary" type="button">Cancel</button>
          <button class="confirm-btn" type="button">Delete</button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("confirm-dialog");
      const openButton = document.querySelector(".trigger");
      const closeButton = dialog.querySelector(".close-btn");
      const cancelButton = dialog.querySelector(".secondary");
      const deleteButton = dialog.querySelector(".confirm-btn");

      openButton.addEventListener("click", () => dialog.showModal());

      const closeDialog = () => dialog.close();

      closeButton.addEventListener("click", closeDialog);
      cancelButton.addEventListener("click", closeDialog);
      deleteButton.addEventListener("click", closeDialog);

      dialog.addEventListener("click", (event) => {
        const rect = dialog.getBoundingClientRect();
        const clickedOutside =
          event.clientX < rect.left ||
          event.clientX > rect.right ||
          event.clientY < rect.top ||
          event.clientY > rect.bottom;

        if (clickedOutside) {
          closeDialog();
        }
      });
    </script>
  </body>
</html>
